using System;using System.Linq;using System.IO;using System.Xml;using System.Drawing;using System.Windows.Forms;
namespace BeamScheduleFormatter {
sealed class ProjectInformation {public string Name="",Location="",Office="",OfficeAddress="";/* date the Program of Works was prepared, yyyy-MM-dd (owner, 19 November 2026) */public string DatePrepared="";
 /* fiscal year and ABC of the project (owner, 23 November 2026: "sa project setting maglagay ng year doon at ABC"); the Contract Duration
    start date uses them (FRONT PAGE!CB7 of the POW workbook) */public string FiscalYear="",Abc="";
 internal int FiscalYearValue{get{int y;return int.TryParse((FiscalYear??"").Trim(),out y)&&y>=1900&&y<=2200?y:0;}}
 internal decimal AbcValue{get{decimal v;return decimal.TryParse((Abc??"").Replace(",","").Trim(),System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out v)&&v>0?v:0;}}internal DateTime? Prepared{get{DateTime d;return DateTime.TryParseExact(DatePrepared??"","yyyy-MM-dd",System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.None,out d)?(DateTime?)d:null;}}
 /* owner (19 November 2026, "yung project information pala dapat laging nauuna, di pwede mag proceed if di nafill up") */
 internal bool Complete{get{return Name.Trim().Length>0&&Location.Trim().Length>0&&Office.Trim().Length>0&&OfficeAddress.Trim().Length>0&&Prepared.HasValue;}}public string NameLine{get{return "Project: "+(Name.Length==0?"(not set)":Name);}}public string LocationLine{get{return "Location: "+(Location.Length==0?"(not set)":Location);}}}
static class ProjectInfoStore {
 internal const int MaxTitleLength=2000,MaxLocationLength=500;
 /* shared by the Store app and the downloaded .exe (Documents\\DTCE Tool Kit\\Settings) */public static string DirectoryPath=SharedData.Folder("Settings","BeamTools","ProjectInformation.xml","ProjectLibrary.xml");
 public static ProjectInformation Read(){string path=Path.Combine(DirectoryPath,"ProjectInformation.xml");if(!File.Exists(path))return new ProjectInformation();var d=new XmlDocument{XmlResolver=null};using(var r=XmlReader.Create(path,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=32768}))d.Load(r);if(d.DocumentElement.Name!="ProjectInformation")throw new Exception("Invalid saved project information.");return new ProjectInformation{Name=d.DocumentElement.GetAttribute("name"),Location=d.DocumentElement.GetAttribute("location"),Office=d.DocumentElement.GetAttribute("office"),OfficeAddress=d.DocumentElement.GetAttribute("officeAddress"),DatePrepared=d.DocumentElement.GetAttribute("prepared"),FiscalYear=d.DocumentElement.GetAttribute("fy"),Abc=d.DocumentElement.GetAttribute("abc")};}
 public static void Save(string name,string location){var current=Read();Save(name,location,current.Office,current.OfficeAddress,current.DatePrepared);}
 /* Owner (18 November 2026): project title / location belong to one Program of Works. A new POW, or a POW file
    without project information, starts blank; the office name and address are kept. */
 public static void ClearProject(){try{var current=Read();if(current.Name.Length>0||current.Location.Length>0||current.DatePrepared.Length>0||current.FiscalYear.Length>0||current.Abc.Length>0)Save("","",current.Office,current.OfficeAddress,"","","");}catch(Exception){}}
 public static void Save(string name,string location,string office,string officeAddress){Save(name,location,office,officeAddress,null);}
 /* prepared == null keeps the saved date prepared */
 public static void Save(string name,string location,string office,string officeAddress,string prepared){Save(name,location,office,officeAddress,prepared,null,null);}
 /* fiscalYear / abc == null keep the saved values */
 public static void Save(string name,string location,string office,string officeAddress,string prepared,string fiscalYear,string abc){if(prepared==null){try{prepared=Read().DatePrepared;}catch(Exception){prepared="";}}if(fiscalYear==null||abc==null){ProjectInformation cur;try{cur=Read();}catch(Exception){cur=new ProjectInformation();}if(fiscalYear==null)fiscalYear=cur.FiscalYear;if(abc==null)abc=cur.Abc;}fiscalYear=(fiscalYear??"").Trim();abc=(abc??"").Trim();if(fiscalYear.Length>10||abc.Length>40)throw new Exception("Check the fiscal year and the ABC.");name=(name??"").Replace("\r\n","\n").Replace('\r','\n').Trim();location=(location??"").Replace("\r\n","\n").Replace('\r','\n').Trim();if(name.Length>MaxTitleLength||location.Length>MaxLocationLength)throw new Exception("Project title supports up to "+MaxTitleLength+" characters; location supports up to "+MaxLocationLength+" characters.");office=(office??"").Trim();officeAddress=(officeAddress??"").Trim();if(office.Length>200||officeAddress.Length>200)throw new Exception("Office and address must be at most 200 characters.");var d=new XmlDocument();var root=d.CreateElement("ProjectInformation");root.SetAttribute("office",office);root.SetAttribute("officeAddress",officeAddress);root.SetAttribute("name",name);root.SetAttribute("location",location);root.SetAttribute("prepared",prepared??"");if(fiscalYear.Length>0)root.SetAttribute("fy",fiscalYear);if(abc.Length>0)root.SetAttribute("abc",abc);d.AppendChild(root);Directory.CreateDirectory(DirectoryPath);string path=Path.Combine(DirectoryPath,"ProjectInformation.xml"),temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{d.Save(temp);if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}
  ProjectCaption.Refresh();
  if(name.Length>0)try{ProjectLibrary.Remember(new ProjectInformation{Name=name,Location=location,Office=office,OfficeAddress=officeAddress,DatePrepared=prepared??"",FiscalYear=fiscalYear,Abc=abc});}catch(Exception){}}
}
/* saved project information kept in the app (owner, 20 November 2026: "sa tabi niya maglagay na lang ng saved Project Info, na
   nakasave sa app. para iclick na lang yung title iloload na lang"): every saved project, newest first, in the user's local
   application data (outside the versioned installation folder) */
static class ProjectLibrary {
 const int MaxEntries=300;
 static string FilePath{get{return Path.Combine(ProjectInfoStore.DirectoryPath,"ProjectLibrary.xml");}}
 static string Key(ProjectInformation p){return (p.Name??"").Trim().ToUpperInvariant()+"\n"+(p.Location??"").Trim().ToUpperInvariant();}
 public static System.Collections.Generic.List<ProjectInformation> List(){var list=new System.Collections.Generic.List<ProjectInformation>();if(!File.Exists(FilePath))return list;var d=new XmlDocument{XmlResolver=null};using(var r=XmlReader.Create(FilePath,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=8000000}))d.Load(r);if(d.DocumentElement==null||d.DocumentElement.Name!="ProjectLibrary")return list;
  foreach(XmlElement e in d.DocumentElement.SelectNodes("Project"))list.Add(new ProjectInformation{Name=e.GetAttribute("name"),Location=e.GetAttribute("location"),Office=e.GetAttribute("office"),OfficeAddress=e.GetAttribute("officeAddress"),DatePrepared=e.GetAttribute("prepared"),FiscalYear=e.GetAttribute("fy"),Abc=e.GetAttribute("abc")});return list;}
 static void Write(System.Collections.Generic.List<ProjectInformation> list){var d=new XmlDocument();var root=d.CreateElement("ProjectLibrary");d.AppendChild(root);foreach(var p in list.Take(MaxEntries)){var e=d.CreateElement("Project");e.SetAttribute("name",p.Name);e.SetAttribute("location",p.Location);e.SetAttribute("office",p.Office);e.SetAttribute("officeAddress",p.OfficeAddress);e.SetAttribute("prepared",p.DatePrepared);if(!string.IsNullOrEmpty(p.FiscalYear))e.SetAttribute("fy",p.FiscalYear);if(!string.IsNullOrEmpty(p.Abc))e.SetAttribute("abc",p.Abc);root.AppendChild(e);}
  Directory.CreateDirectory(ProjectInfoStore.DirectoryPath);string temp=FilePath+"."+Guid.NewGuid().ToString("N")+".tmp";try{d.Save(temp);if(File.Exists(FilePath))File.Replace(temp,FilePath,null);else File.Move(temp,FilePath);}finally{if(File.Exists(temp))File.Delete(temp);}}
 /* adds or refreshes a project (same title and location) and moves it to the top */
 public static void Remember(ProjectInformation p){if(string.IsNullOrWhiteSpace(p.Name))return;var list=List();list.RemoveAll(x=>Key(x)==Key(p));list.Insert(0,p);Write(list);}
 public static void Remove(ProjectInformation p){var list=List();list.RemoveAll(x=>Key(x)==Key(p));Write(list);}
}
