  var saved=new ListBox{Dock=DockStyle.Fill,DrawMode=DrawMode.OwnerDrawFixed,ItemHeight=58,IntegralHeight=false,BorderStyle=BorderStyle.FixedSingle};var remove=new Button{Text="Remove from the list",Dock=DockStyle.Bottom,Height=34};var gap=new Panel{Dock=DockStyle.Top,Height=8};
  side.Controls.Add(saved);side.Controls.Add(gap);side.Controls.Add(search);side.Controls.Add(searchLabel);side.Controls.Add(sideNote);side.Controls.Add(sideTitle);side.Controls.Add(remove);Controls.Add(side);side.SendToBack();
